import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Interface: ModuleMetadata","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/interfaces/ModuleMetadata.md","filePath":"api/twine/interfaces/ModuleMetadata.md"}'),i={name:"api/twine/interfaces/ModuleMetadata.md"};function n(d,e,c,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../">twine</a> / ModuleMetadata</p><h1 id="interface-modulemetadata" tabindex="-1">Interface: ModuleMetadata <a class="header-anchor" href="#interface-modulemetadata" aria-label="Permalink to &quot;Interface: ModuleMetadata&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L128" target="_blank" rel="noreferrer">module.interface.ts:128</a></p><p>Metadata attached to a class by the <a href="./../functions/Module.html">Module</a> decorator.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="activebydefault" tabindex="-1">activeByDefault? <a class="header-anchor" href="#activebydefault" aria-label="Permalink to &quot;activeByDefault?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>activeByDefault?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L160" target="_blank" rel="noreferrer">module.interface.ts:160</a></p><p>Initial state of an <code>area</code>&#39;s flag, set in <code>load</code>. Default <code>false</code> - areas start inactive and are switched on by a trigger (a level you enter, etc.). Set <code>true</code> for an area that should be live from load.</p><hr><h3 id="area" tabindex="-1">area? <a class="header-anchor" href="#area" aria-label="Permalink to &quot;area?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>area?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L153" target="_blank" rel="noreferrer">module.interface.ts:153</a></p><p>Mark this module as an <strong>area</strong>: it owns an <code>active</code> scoreboard flag, and its own <code>onTick</code> <em>and the entire subtree of modules it imports</em> run only while that flag is <code>1</code>. An inactive area costs a single <code>execute if score … active</code> check per tick - everything beneath it (including children&#39;s proximity checks) is skipped. Flip it with the generated <code>&lt;name&gt;/activate</code> / <code>&lt;name&gt;/deactivate</code> functions, or a regionTrigger/scoreTrigger.</p><hr><h3 id="dimension" tabindex="-1">dimension? <a class="header-anchor" href="#dimension" aria-label="Permalink to &quot;dimension?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>dimension?</strong>: <code>IdValue</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L180" target="_blank" rel="noreferrer">module.interface.ts:180</a></p><p>The dimension this <code>area</code> lives in. When set, twine runs the area&#39;s whole lifecycle <em>in</em> it: <code>onActivate</code>/<code>onDeactivate</code>, the throttled <code>onTick</code>/<code>@On</code> subtree, and the arm/presence detectors are each wrapped in <code>execute in &lt;dimension&gt; run …</code>. A feature states &quot;I live in the End&quot; once, instead of every handler re-adding <code>.in(...)</code> and one silently forgetting - a positional trigger, or a block/<code>from block</code> read inside a handler, then resolves against the area&#39;s dimension rather than against wherever the tick loop happens to run (the overworld). Child areas inherit it, so a nested area need only name a dimension when it differs from its parent&#39;s. Only meaningful on an <code>area</code> module.</p><hr><h3 id="env" tabindex="-1">env? <a class="header-anchor" href="#env" aria-label="Permalink to &quot;env?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>env?</strong>: <a href="./../type-aliases/BuildEnv.html"><code>BuildEnv</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L188" target="_blank" rel="noreferrer">module.interface.ts:188</a></p><p>Restrict the module to specific build environments. When set, the module (and any modules reachable only through it) is compiled in only if the active <a href="./../type-aliases/BuildEnv.html">BuildEnv</a> is listed - e.g. <code>env: [&quot;dev&quot;]</code> for debug-only features that must never reach a prod build. Omit to include in all envs.</p><hr><h3 id="imports" tabindex="-1">imports? <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;imports?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>imports?</strong>: <a href="./../type-aliases/ModuleRef.html"><code>ModuleRef</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L143" target="_blank" rel="noreferrer">module.interface.ts:143</a></p><p>Child modules to compose in (NestJS-style): decorated classes and/or <a href="./ConfiguredModule.html">ConfiguredModule</a>s. Listing a module here enables it; removing it disables it at compile time. References are de-duplicated by identity, so the same class (or the same configured instance) imported by several parents is only built once - but two separate <code>Door(...)</code> calls are two distinct doors.</p><hr><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L133" target="_blank" rel="noreferrer">module.interface.ts:133</a></p><p>Stable identifier for the module. Used as the scoreboard fake-player id (<code>#&lt;name&gt; modules</code>) and as the namespace for the enable/disable functions.</p><hr><h3 id="tickevery" tabindex="-1">tickEvery? <a class="header-anchor" href="#tickevery" aria-label="Permalink to &quot;tickEvery?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>tickEvery?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L197" target="_blank" rel="noreferrer">module.interface.ts:197</a></p><p>Throttle this module&#39;s <code>onTick</code>: run it once every <code>tickEvery</code> ticks instead of every tick. Wrapped <em>inside</em> any area gating, so it still costs nothing while an ancestor area is dormant - this just spreads out the work while active. Omit (or <code>1</code>) to run every tick. Use for per-tick work that doesn&#39;t need 20 Hz (proximity sweeps, slow timers) to cut per-tick command volume.</p><hr><h3 id="tickphase" tabindex="-1">tickPhase? <a class="header-anchor" href="#tickphase" aria-label="Permalink to &quot;tickPhase?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>tickPhase?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L206" target="_blank" rel="noreferrer">module.interface.ts:206</a></p><p>The offset (in ticks, <code>0..tickEvery-1</code>) at which this module&#39;s throttled <code>onTick</code> fires within its period. Lets you deliberately spread same-period modules across different ticks. Omit to have the factory auto-assign distinct phases round-robin across modules sharing a <code>tickEvery</code>, so they don&#39;t all fire on the same tick. Only meaningful with <code>tickEvery</code> set.</p><hr><h3 id="trigger" tabindex="-1">trigger? <a class="header-anchor" href="#trigger" aria-label="Permalink to &quot;trigger?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>trigger?</strong>: <a href="./../type-aliases/AreaTrigger.html"><code>AreaTrigger</code></a></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/module.interface.ts#L166" target="_blank" rel="noreferrer">module.interface.ts:166</a></p><p>How this <code>area</code> switches itself on (see <a href="./../type-aliases/AreaTrigger.html">AreaTrigger</a>). Omit to activate it manually via the generated <code>&lt;name&gt;/activate</code> function.</p>',49)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
